1	/**
2	 * Private helpers shared by the service layer.
3	 *
4	 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
5	 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
6	 * Neither re-implements a cross-cutting concern — they are adapters onto
7	 * `@/lib/permissions` and `@/lib/event-bus`.
8	 */
9	import { toIsoTimestamp } from "@/types/common";
10	import type { Comment } from "@/types/comment";
11	import type { OrgId, UserId } from "@/types/common";
12	import type { EventEnvelope } from "@/types/event";
