/**
 * A label picker can be sent stale ids from another workspace or a since
 * deleted label. Every id must resolve to one of this org's own live labels,
 * or the write is refused rather than silently attaching a foreign label.
 */
async function assertOwnLabels(
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;
  const found = await labelRepo.findLabelsByIds(orgId, labelIds);
  if (found.length !== new Set(labelIds).size) {
    throw new NotFoundError("Label", labelIds.join(","));
  }
}

/**
 * A parent must be a live issue of the same project — never a different
 * workspace, a different project of the same workspace, or an archived issue.
 */
async function assertValidParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<void> {
  if (parentId === null) return;
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (!parent || parent.projectId !== projectId || parent.archivedAt !== null) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** An assignee must be a current, active member of the org being changed. */
async function assertAssignableMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
}

