/**
 * A label picker can be sent stale ids from another workspace or a since
 * deleted label. Every id must resolve to one of this org's own live labels,
 * or the write is refused rather than silently attaching a foreign label.
 */
async function assertOwnLabels(
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;
  const found = await labelRepo.findLabelsByIds(orgId, labelIds);
  if (found.length !== new Set(labelIds).size) {
    throw new NotFoundError("Label", labelIds.join(","));
  }
}

/**
 * A parent must be a live issue of the same project — never a different
 * workspace, a different project of the same workspace, or an archived issue.
 */
async function assertValidParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<void> {
  if (parentId === null) return;
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (!parent || parent.projectId !== projectId || parent.archivedAt !== null) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** An assignee must be a current, active member of the org being changed. */
async function assertAssignableMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
}

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  await assertValidParent(input.orgId, input.projectId, input.parentId);
  await assertOwnLabels(input.orgId, input.labelIds);
  if (input.assigneeId !== null) {
    await assertAssignableMember(input.orgId, input.assigneeId);
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

