/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side, restricted to people who are actually
 * current members of this org. A mention of anyone else — whether typed as
 * `@handle` or supplied by the composer's suggestions — is dropped rather
 * than notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const memberIds = new Set(
    members.items
      .filter((member) => member.status === "active")
      .map((member) => member.userId),
  );

  return [...new Set([...resolved, ...clientProvided])].filter((id) =>
    memberIds.has(id),
  );
}

